-- Run on remote D1; every statement idempotent.
CREATE TABLE IF NOT EXISTS sessions (id TEXT PRIMARY KEY,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,expires_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS usage_limits (day TEXT NOT NULL,scope TEXT NOT NULL,used INTEGER NOT NULL DEFAULT 0,PRIMARY KEY(day,scope));
CREATE TABLE IF NOT EXISTS works (id TEXT PRIMARY KEY,owner TEXT NOT NULL,tool_id TEXT NOT NULL,prompt TEXT NOT NULL DEFAULT '',title TEXT NOT NULL DEFAULT '',body TEXT NOT NULL DEFAULT '',tags TEXT NOT NULL DEFAULT '[]',created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS idx_works_owner_created ON works(owner,created_at DESC);
CREATE TABLE IF NOT EXISTS assets (id TEXT PRIMARY KEY,owner TEXT NOT NULL,object_key TEXT NOT NULL,mime TEXT NOT NULL,size INTEGER NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS idx_assets_owner_created ON assets(owner,created_at DESC);
